window.__votdWeek && window.__votdWeek({"week":"2028-02-28","reading":"2 Nephi 20–25","days":[{"d":"2028-02-28","ref":"2 Nephi 20:33","b":"2 Nephi","c":20,"v":33,"he":"הִנֵּה הָאָדוֹן יְהוָה צְבָאוֹת מְסָעֵף פֻּארָה בְּמַעֲרָצָה וְרָמֵי הַקּוֹמָה גְּדוּעִים וְהַגְּבֹהִים יִשְׁפָּלוּ׃","en":"Behold, the Lord, the Lord of Hosts shall lop the bough with terror; and the high ones of stature shall be hewn down; and the haughty shall be humbled."},{"d":"2028-02-29","ref":"2 Nephi 21:10","b":"2 Nephi","c":21,"v":10,"he":"וְהָיָה בַּיּוֹם הַהוּא שֹׁרֶשׁ יִשַׁי אֲשֶׁר עֹמֵד לְנֵס עַמִּים אֵלָיו גּוֹיִם יִדְרֹשׁוּ וְהָיְתָה מְנֻחָתוֹ כָּבוֹד׃","en":"And in that day there shall be a root of Jesse, which shall stand for an ensign of the people; to it shall the Gentiles seek; and his rest shall be glorious."},{"d":"2028-03-01","ref":"2 Nephi 21:16","b":"2 Nephi","c":21,"v":16,"he":"וְהָיְתָה מְסִלָּה לִשְׁאָר עַמּוֹ אֲשֶׁר יִשָּׁאֵר מֵאַשּׁוּר כַּאֲשֶׁר הָיְתָה לְיִשְׂרָאֵל בְּיוֹם עֲלֹתוֹ מֵאֶרֶץ מִצְרָיִם׃","en":"And there shall be a highway for the remnant of his people which shall be left, from Assyria, like as it was to Israel in the day that he came up out of the land of Egypt."},{"d":"2028-03-02","ref":"2 Nephi 23:11","b":"2 Nephi","c":23,"v":11,"he":"וּפָקַדְתִּי עַל־תֵּבֵל רָעָה וְעַל־רְשָׁעִים עֲוֹנָם וְהִשְׁבַּתִּי גְּאוֹן זֵדִים וְגַאֲוַת עָרִיצִים אַשְׁפִּיל׃","en":"And I will punish the world for evil, and the wicked for their iniquity; I will cause the arrogancy of the proud to cease, and will lay down the haughtiness of the terrible."},{"d":"2028-03-03","ref":"2 Nephi 24:20","b":"2 Nephi","c":24,"v":20,"he":"לֹא־תֵחַד אִתָּם בִּקְבוּרָה כִּי־אַרְצְךָ שִׁחַתָּ עַמְּךָ הָרָגְתָּ לֹא־יִקָּרֵא לְעוֹלָם זֶרַע מְרֵעִים׃","en":"Thou shalt not be joined with them in burial, because thou hast destroyed thy land and slain thy people; the seed of evil-doers shall never be renowned."},{"d":"2028-03-04","ref":"2 Nephi 25:17","b":"2 Nephi","c":25,"v":17,"he":"וְיוֹסִיף יְהוָה שֵׁנִית יָדוֹ לְהָשִׁיב עַמּוֹ מֵאֲבֵדָתָם וּנְפִילָתָם לָכֵן יוֹסִיף לְהַפְלִיא הַפְלֵא וָפֶלֶא בִּבְנֵי הָאָדָם׃","en":"And the Lord will set his hand again the second time to restore his people from their lost and fallen state. Wherefore, he will proceed to do a marvelous work and a wonder among the children of men."},{"d":"2028-03-05","ref":"2 Nephi 25:23","b":"2 Nephi","c":25,"v":23,"he":"כִּי עֲמֵלִים אֲנַחְנוּ בַּחֲרִיצוּת לִכְתֹּב לְהוֹכִיחַ בָּנֵינוּ וְאַחֵינוּ לְהַאֲמִין בַּמָּשִׁיחַ וּלְהִתְרַצּוֹת אֶל־אֱלֹהִים כִּי יָדַעְנוּ כִּי בְחֶסֶד נִוָּשַׁע אַחֲרֵי כׇּל־אֲשֶׁר נוּכַל לַעֲשׂוֹת׃","en":"For we labor diligently to write, to persuade our children, and also our brethren, to believe in Christ, and to be reconciled to God; for we know that it is by grace that we are saved, after all we can do."}]});
